function tp(t){try{return JSON.parse(t)}catch{return null}}
function ext(j){let d=j;const t1=d?.content?.parts?.[0]?.text;if(typeof t1==='string'){const p=tp(t1);if(p)d=p;}
const t2=d?.message?.content;if(typeof t2==='string'){const p=tp(t2);if(p)d=p;}return d;}
function pb(v){return typeof v==='boolean'?v:typeof v==='string'?['true','sim','yes'].includes(v.toLowerCase()):false;}

const atual=$('Inicio').first().json.chamado;
const raw=$input.first().json||{};
const hist=$('PG: Historico Dedup').all().map(i=>i.json);
if(raw.error){
  const msg=raw.error?.message||raw.error||'Erro na IA de deduplicacao';
  return[{json:{chamado:atual,erro_ia:true,mensagem_erro:String(msg),duplicidade:{eh_duplicado:false,chamado_referencia_id:null,chamado_referencia:null,justificativa:'IA indisponivel',caracteristicas_match:[]}}}];
}
const r=ext(raw)||{};
const dup=r.duplicidade||r;
if(!Object.prototype.hasOwnProperty.call(dup,'eh_duplicado')){
  return[{json:{chamado:atual,erro_ia:true,mensagem_erro:'Resposta da IA sem campo eh_duplicado',duplicidade:{eh_duplicado:false,chamado_referencia_id:null,chamado_referencia:null,justificativa:'Resposta invalida da IA',caracteristicas_match:[]}}}];
}
const eh=pb(dup.eh_duplicado);
const refId=Number(dup.chamado_referencia_id);
const ref=Number.isFinite(refId)?hist.find(h=>Number(h.id)===refId):null;

return[{json:{chamado:atual,duplicidade:{
  eh_duplicado:eh,chamado_referencia_id:eh&&Number.isFinite(refId)?refId:null,
  chamado_referencia:ref||null,
  justificativa:dup.justificativa||dup.justificativa_para_fiscal||'Sem justificativa',
  caracteristicas_match:Array.isArray(dup.caracteristicas_match)?dup.caracteristicas_match:[]
},erro_ia:false,mensagem_erro:null}}];

