function tp(t){try{return JSON.parse(t)}catch{return null}}
function ext(j){let d=j;const t1=d?.content?.parts?.[0]?.text;if(typeof t1==='string'){const p=tp(t1);if(p)d=p;}
const t2=d?.message?.content;if(typeof t2==='string'){const p=tp(t2);if(p)d=p;}return d;}
const ch=$('PG: Marcar Classificando').first().json;
const raw=$input.first().json||{};
if(raw.error){
  const msg=raw.error?.message||raw.error||'Erro na IA de classificacao';
  return[{json:{chamado:ch,erro_ia:true,mensagem_erro:String(msg)}}];
}
let r=ext(raw)||{};
let tipo=String(r.tipo||'').toUpperCase().trim();
let exec=String(r.executor||'').toUpperCase().trim();
const tv=['INVIAVEL','OBRA','MANUTENCAO'].includes(tipo);
const ev=['NENHUM','DDI_DG','DEMO','SOB_DEMANDA'].includes(exec);
if(!tv||!ev||(tipo==='INVIAVEL'&&exec!=='NENHUM')||(tipo==='OBRA'&&exec!=='DDI_DG')||
(tipo==='MANUTENCAO'&&!['DEMO','SOB_DEMANDA'].includes(exec))){
  return[{json:{chamado:ch,erro_ia:true,mensagem_erro:'Resposta da IA com tipo/executor invalido'}}];
}
if(tipo==='INVIAVEL')exec='NENHUM';if(tipo==='OBRA')exec='DDI_DG';
return[{json:{chamado:ch,classificacao:{tipo,executor:exec,
categoria:r.categoria||'',justificativa:r.justificativa||'Classificado por IA',
mensagem_solicitante:r.mensagem_solicitante||''},erro_ia:false,mensagem_erro:null}}];

